// pub fn calculate_average
function calculate_average(values) {
  let sum = 0.0;
  let count = 0;
  let i = 0;
  while (i < (values || []).length) {
  sum = sum + (values || [])[i];
  count = count + 1;
  i = i + 1;
  }
  if (count !== 0) {
  return sum / count;
  }
  return 0.0;
}


